PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE starred_media (
  id TEXT PRIMARY KEY,
  created_at TEXT NOT NULL,
  media_url TEXT NOT NULL,
  media_width INTEGER NOT NULL,
  media_height INTEGER NOT NULL
);
CREATE TABLE users (
  email TEXT PRIMARY KEY,
  role TEXT NOT NULL CHECK (role IN ('admin', 'member')),
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE signin_codes (
  code TEXT PRIMARY KEY,
  email TEXT NOT NULL,
  expires_at TEXT NOT NULL
);
CREATE TABLE admin_table_config (
  table_name TEXT PRIMARY KEY,
  config TEXT NOT NULL DEFAULT '{}'
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_starred_media_created_at ON starred_media(created_at);
CREATE INDEX idx_signin_codes_email ON signin_codes(email);
CREATE INDEX idx_signin_codes_expires_at ON signin_codes(expires_at);
